insert into categories (id, glide_row_id, name, slug, description) values ('ac44265a-44eb-505b-81d0-29a0554f814c', 'Rj56tRuZT.WO-mPsrkmqlQ', 'Interpolation', 'interpolation', 'This is a collection of songs that interpolate other songs. In popular music, interpolation (also called a replayed sample) refers to using a melody—or portions of a melody (often with modified lyrics)—from a previously recorded song but re-recording the melody instead of directly sampling it. Songs that are cover versions, parodies, or use samples of other songs are not included.');
