insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('c7aa8a87-6904-580b-8ced-f655a402484c', '7U1fMwefSoiiEVzozz3Czw', 'land-of-1000-dances-cannibal-the-headhunters', 'Land of 1000 Dances', 'efcebd75-41c8-57e7-8434-abaf17911481', 'https://i.scdn.co/image/ab67616d0000b273db17102660b1be6234bace49', 'https://open.spotify.com/track/2boQ0A6CkYdKhBn250tc4r', null, 'https://song.link/s/2boQ0A6CkYdKhBn250tc4r', null, null, null, null, null, null, true);
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('9d33cab5-6bb0-5249-ab50-6a435e3080ec', 'ylmLx6fCR36eor5XEscYlg', 'constructive-summer-the-hold-steady', 'Constructive Summer', 'f4b7dfe9-b378-5be2-9a7a-45a359105f69', 'https://i.scdn.co/image/ab67616d0000b2739a84904a16288684e73115c9', 'https://open.spotify.com/track/6ulHEJ6bVJ0afE8xzz6P9B', null, 'https://song.link/s/6ulHEJ6bVJ0afE8xzz6P9B', null, '> For anyone who has ever found community in fellow rock nerds, pounding out a drum beat is something like third base. “Me and my friends are like the drums on ‘Lust for Life’”. Craig Finn understands the way music can unite people, become a shorthand, and eventually enter your vocabulary subconsciously. “Me and my friends are like ''Double-whiskey coke, no ice''“. Iggy Pop and The Dillinger Four share space on The Hold Steady’s breakneck opener to 2008’s underrated Stay Positive, evoking the sacred bonds music fans share everywhere from the studio to the bar.', 'https://www.treblezine.com/10-essential-songs-that-reference-other-songs/', null, null, null, true);
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('b519824b-b74c-527d-990f-817145ff0432', 'a.DAcHaS9Q9ST7ar9Ac2DEQ', 'lust-for-life-iggy-pop', 'Lust for Life', 'ce15c86d-8758-501d-bcbf-19dc724a1f2c', 'https://i.scdn.co/image/ab67616d0000b2734aa5f679427e35409a06f225', 'https://open.spotify.com/track/21YxK0klhpfLW8budkJaMF', null, 'https://song.link/s/21YxK0klhpfLW8budkJaMF', null, null, null, null, null, null, true);
