insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('bcc76c39-329b-5e1e-8c6e-1147b2a4311d', 'KtWf8CxxTNGxxka.zsMBpA', 'whatever-oasis', 'Whatever', 'a577493d-91ab-56ac-9855-f904fcfed658', 'https://i.scdn.co/image/ab67616d0000b273d86a1e021e7acc7c07c7d668', 'https://open.spotify.com/track/5OWsea313ovaQoXvsgWq79', null, 'https://song.link/s/5OWsea313ovaQoXvsgWq79', null, 'Oasis settled out of court with EMI as the record label claimed that the song borrowed portions of Neil Innes''s "How Sweet to Be an Idiot". Innes received a songwriting credit and a share of the royalties. The portion of the melodic line in question are the eight notes that accompany the lyrics "I''m free to be whatever I".', null, null, null, null, true);
