insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('f030459b-6c31-5561-8a92-9021e73ded4d', 'OpjYUWVARU-u8RSvrApysw', 'birthday-boy-ween', 'Birthday Boy', '616ab204-67ff-5026-be01-7af4f4eca4cb', 'https://i.scdn.co/image/ab67616d0000b273b732177bee49f1c20edd2f19', 'https://open.spotify.com/track/3mKFCngvUNBqUZYw3j2k4N', null, 'https://song.link/s/3mKFCngvUNBqUZYw3j2k4N', null, 'The end of the song features audio clips of real-life answering machine messages from Gene''s father and mother, wishing him a happy 20th birthday. At the very end of the track, a brief snippet of the Pink Floyd song "Echoes" can be heard.', 'https://www.ween.wiki/wiki/Birthday_Boy', null, null, null, true);
