insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('4619ae0f-6193-58f6-b460-e319a3e4eac0', 'r3d1jSIQSJ2.BJHWTclCVQ', 'you-never-even-called-me-by-my-name-david-allan-coe', 'You Never Even Called Me By My Name', '60626b2c-6bad-5820-a48a-b04c50f0aabd', 'https://i.scdn.co/image/ab67616d0000b273243cc5bc1bb1f6ab8002a35c', 'https://open.spotify.com/track/29TI0GvP5gMQMPTJjdMe0H', null, 'https://song.link/s/29TI0GvP5gMQMPTJjdMe0H', null, '> "You Never Even Called Me by My Name" is a song written by Steve Goodman and John Prine. Prine requested to be uncredited on the song, as he thought it was a "goofy, novelty song" and did not want to "offend the country music community". Goodman released the song on his 1971 debut album Steve Goodman to little acclaim. It was more famously recorded by country music singer David Allan Coe on his 1975 album Once Upon a Rhyme. It was the third single release of Coe''s career and his first Top Ten hit, reaching a peak of number eight on the Billboard country singles charts. The song, over five minutes long, is known for its humorous self-description as "the perfect country and western song."
