insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('48bcbfd0-222f-5df0-9df3-9af1ba080f5f', 'q7tNsw2HSMSVsUMvDajDpQ', 'drive-r-e-m', 'Drive', 'c15c6fb9-4aaf-5182-af2b-4599f912646a', 'https://i.scdn.co/image/ab67616d0000b273ace3e7aae0b7c78bbe1c4f35', 'https://open.spotify.com/track/3geRffSf6eAruhg23RkpKV', null, 'https://song.link/s/3geRffSf6eAruhg23RkpKV', null, 'The lyric "Hey, kids, rock ''n'' roll" is an homage to the song "Stop It" by fellow Athens, Georgia, group Pylon; Stipe has also said the song is an "obvious homage to ''Rock On'' by David Essex which features a similar line.', 'https://en.wikipedia.org/wiki/Drive_(R.E.M._song)', null, null, null, true);
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('dfd11ecd-f35b-5f8e-a766-96690220af7b', 'wMKvhzTiQnyDQqw9fex20A', 'she-loves-you-the-beatles', 'She Loves You', '81cd14a1-5cfe-5f02-9bb6-cb8d382e70af', 'https://i.scdn.co/image/ab67616d0000b2734a4c7445df9b3719a60eb53b', 'https://open.spotify.com/track/6nEkxYIEnrbYH7h1hJ8Xn6', null, 'https://song.link/s/6nEkxYIEnrbYH7h1hJ8Xn6', null, null, null, null, null, null, true);
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('12000bd3-3838-5bc1-96e0-260d8df8d293', '0CoxXI2UTMO4s0zHu2-Bbg', 'you-cant-do-that-harry-nilsson', 'You Can''t Do That', 'e46af056-ae0c-5116-9bf6-b2e3e94cf63c', 'https://i.scdn.co/image/ab67616d0000b273e3da53aa281e334170335f83', 'https://open.spotify.com/track/7MebA2C5foeChyR0P4ER8L', null, 'https://song.link/s/7MebA2C5foeChyR0P4ER8L', null, '> In theory, it’s a cover of the Beatles’ 1964 song, but with its cascading overdubs and interwoven lyrics from other Beatles songs, Nilsson creates what I’ll call the first mash-up. It’s a pastiche of at least 14 different songs (some say 22), from “I Want to Hold Your Hand” to “Day Tripper,” “Paperback Writer” to “Strawberry Fields Forever.”10 It’s a fascinating track, blending phrases of melody and lyrics, and it’s all over in just 140 seconds. But there’s something fanboyish about “You Can’t Do That.” It’s a cry for attention, which, of course, it got.', 'https://grantland.com/features/the-legacy-harry-nilsson/', 'Pandemonium Shadow Show', null, null, true);
