insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('26f452a8-1a5c-5ffe-8b47-60103a32ac18', 'a-PWfb8JcROGcC3CZ7j-vFA', 'plus-ones-okkervil-river', 'Plus Ones', '40ef7fd7-c1cd-523b-be08-232df2371951', 'https://i.scdn.co/image/ab67616d0000b2732ccd8f36020146381bf680e4', 'https://open.spotify.com/track/5vV4vLNilXyGxX7irLGFBT', null, 'https://song.link/s/5vV4vLNilXyGxX7irLGFBT', 'No one wants to hear about your 97th tear
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('fbe3b910-bb95-553e-bfde-dcff8c1aa68a', 'a-gSbDo10T9m-WBKe.50H.A', 'true-love-pt-2-x', 'True Love - Pt. 2', '2a6124e6-bbac-5a26-897b-88d2706cbc40', 'https://i.scdn.co/image/ab67616d0000b2735809da220e5f01e78ba9db92', 'https://open.spotify.com/track/2XqdHmsmTTxfQBZ1TTjSy4', null, 'https://song.link/s/2XqdHmsmTTxfQBZ1TTjSy4', null, '> The final track on More Fun in the New World, "True Love, Pt. 2" (part one was a completely different song on side one) had a funky, R&B-oriented rhythm guitar part and DJ Bonebrake backs it up with a solid beat. Other descriptions of this sound have included ''dance-oriented'' or even ''disco,'' which is goofy considering this was 1983. John and Exene sing about true love listing its attributes: it is the devil''s crow bar, suitcase, zip gun, car crash. Finally this melds into a series of musical quotations from a long list of American folk songs, nursery rhymes, blues roots, and more: "I''ve Been Working on the Railroad," "Black Betty," "Old MacDonald." It marked the way that X, like many of the hippies before them, had turned toward traditional American music to express their experiences and views of modern life.', 'https://newdirectionsinmusic.substack.com/p/45-years-with-x', null, null, null, true);
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('42032eba-e084-546d-9940-a0ca116a09d8', 'QWVwTlv3Tq2I93to0xZFwA', 'strawberry-fields-forever-the-beatles', 'Strawberry Fields Forever', '81cd14a1-5cfe-5f02-9bb6-cb8d382e70af', 'https://i.scdn.co/image/ab67616d0000b273692d9189b2bd75525893f0c1', 'https://open.spotify.com/track/3Am0IbOxmvlSXro7N5iSfZ', null, 'https://song.link/s/3Am0IbOxmvlSXro7N5iSfZ', null, null, null, null, null, null, true);
insert into songs (id, glide_row_id, slug, title, artist_id, image_url, spotify_url, apple_music_url, song_link_url, meta_lyrics, description, source_url, album, featured_artists, sentiment, published) values ('4318c1b0-25b9-5bd7-a8e0-0a2726492068', 'u-kD1y0kQMSEi9u5dKiQbA', 'one-headlight-the-wallflowers', 'One Headlight', 'd64252a3-0b41-5487-a06a-60316def9417', 'https://i.scdn.co/image/ab67616d0000b273e542fbcf1a83b7c726eb50a6', 'https://open.spotify.com/track/0z1b34WikhOH9ZxU8QDWcv', null, 'https://song.link/s/0z1b34WikhOH9ZxU8QDWcv', null, '> I was definitely self-conscious when we were sitting down to rehearse it. I think I sang the first verse and he did the second and we were going to trade lines on the last verse. I saw it coming up: He’s going to end up with the line that I basically took from him. “I turn the engine but the engine doesn’t turn.” His song “One Step Up,” “Hit the engine but she ain’t turnin.’” I just saw it on the page below me and said “Goddamn it, it’s going to fall in his lap.” Before he got to it I pointed at it and I was like, “You know, I took that line from you.” He laughed and said “Yeah I know.” Which is the nicest thing he could say at the time. It’s also just fair game. He’s understanding. That’s what rock ’n’ roll is. I didn’t take a song, I took a bit from one of his songs, and we all do that.
